package in.sagarai.controller; import in.sagarai.entity.Vessel; import in.sagarai.repository.VesselRepository; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/vessels") public class VesselController { private final VesselRepository r; public VesselController(VesselRepository r){this.r=r;} @GetMapping public List<Vessel> all(){return r.findAll();} @PostMapping public Vessel create(@RequestBody Vessel v){return r.save(v);} @PutMapping("/{id}") public Vessel update(@PathVariable Long id,@RequestBody Vessel v){v.setImoNumber(v.getImoNumber()); v.setStatus(v.getStatus()); return r.findById(id).map(x->{x.setName(v.getName());x.setImoNumber(v.getImoNumber());x.setStatus(v.getStatus());x.setLatitude(v.getLatitude());x.setLongitude(v.getLongitude());return r.save(x);}).orElseThrow();} }
